function getOrderMessage(status) {
  switch (status) {
    case 'paid': return '결제 완료';
    case 'shipping': return '배송 중입니다';
    case 'done': return '배송 완료';
    default: return '상태 확인 중';
  }
}

function getSeatPrice(grade) {
  let price = 0;
  switch (grade) {
    case 'VIP':
      price = 50000;
      break;
    case 'R':
      price = 30000;
      break;
    case 'S':
      price = 20000;
      break;
    default:
      price = 0;
  }
  return price;
}

function isOpen(day) {
  switch (day) {
    case 'MON':
    case 'TUE':
      return true;
    case 'SUN':
      return false;
    default:
      return false;
  }
}
